--
-- Table structure for table `acr_verifications`
--

DROP TABLE IF EXISTS `acr_verifications`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `acr_verifications` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `acr_id` bigint unsigned NOT NULL,
  `role_slot` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL,
  `user_id` bigint unsigned DEFAULT NULL,
  `actor_name_snapshot` varchar(160) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `actor_position_snapshot` varchar(160) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `verified_at` timestamp NULL DEFAULT NULL,
  `remarks` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `acr_verifications_acr_id_role_slot_unique` (`acr_id`,`role_slot`),
  KEY `acr_verifications_user_id_foreign` (`user_id`),
  CONSTRAINT `acr_verifications_acr_id_foreign` FOREIGN KEY (`acr_id`) REFERENCES `acrs` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `acr_verifications_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=44 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `acr_verifications`
--

LOCK TABLES `acr_verifications` WRITE;
/*!40000 ALTER TABLE `acr_verifications` DISABLE KEYS */;
