INSERT INTO `cqi_issues` VALUES (1,1,NULL,'Student feedback survey indicated Docker CLI setup on Windows Home caused configuration delays in week 2.','Inconsistent local virtualization environments among learners.','3 students delayed initial lab submission by 2 days.','medium','2026-09-17 01:42:39'),(2,3,NULL,'Two learners requested additional visual walkthroughs for Red-Black tree rotations.','Static slide diagrams lacked step-by-step pointer animation.','Lower average score on Q2 of Module 2 test.','low','2026-08-27 10:00:00'),(3,4,NULL,'One learner failed Module 2 DAST capstone (34%) due to local Docker RAM exhaustion.','OWASP ZAP headless scan container requires >4GB dedicated RAM.','Cohort completion rate dropped to 75%.','high','2026-10-27 10:00:00'),(4,5,NULL,'Learners asked for Maven & Gradle dual build templates in Module 2.','Starter repo only included Maven pom.xml.','Minor setup questions in Week 5 forum.','low','2026-10-07 10:00:00');
