INSERT INTO `credential_revisions` VALUES (1,2,2,'corrected','{\"code\": \"CND03-9P4RQ\", \"name\": {\"en\": \"Cloud Native Development\", \"ms\": \"Pembangunan Asal Awan\"}, \"claims\": {\"qv\": true, \"mqf\": 4, \"credit\": \"2.0\", \"qv_until\": \"2026-12-15\"}, \"holder\": \"Bee Tan\", \"issued\": \"2026-10-15T00:00:00Z\", \"issuer\": \"Universiti Teknikal Malaysia Melaka\", \"number\": \"UTEM-MC-2026-0002-R1\", \"stages\": null, \"category\": \"SAMC\", \"outcomes\": {\"en\": [\"Package cloud-ready container images.\", \"Deploy microservices to Kubernetes.\"], \"ms\": [\"Membungkus imej kontena.\", \"Menyebarkan mikroperkhidmatan.\"]}, \"signatory\": \"Hakim Rahman\", \"slt_hours\": 80, \"statement\": {\"en\": \"This credential represents standalone micro-credential completion.\", \"ms\": \"Kredensial ini mewakili penamatan mikro-kredensial.\"}, \"assessment_basis\": \"Verified marks: Docker Lab (50%), Kubernetes Project (50%). Completion confirmed by the deputy dean.\"}','eyJhbGci...corrected_token','Legal name on national identity card verified by CODL registry.',12,'2026-10-15 01:42:39'),(2,10,2,'revoked','{\"code\": \"SEC03-2P6RW\", \"name\": {\"en\": \"Secure Software Development Lifecycle (SSDLC)\", \"ms\": \"Kitar Hayat Pembangunan Perisian Selamat (SSDLC)\"}, \"claims\": {\"qv\": true, \"mqf\": 6, \"credit\": \"2\", \"qv_until\": \"2029-08-15\"}, \"holder\": \"TAN LI\", \"issued\": \"2026-10-26T10:00:00+00:00\", \"issuer\": \"Universiti Teknikal Malaysia Melaka\", \"number\": \"UTEM-MC-2026-0009\", \"stages\": {\"en\": \"Completing this micro-credential, receiving an Academic Credit Record, depositing credit to the Academic Bank of Credit and transferring credit are separate decisions.\", \"ms\": \"Menamatkan micro-credential ini, menerima Academic Credit Record, mendepositkan kredit ke Academic Bank of Credit dan memindahkan kredit adalah keputusan yang berasingan.\"}, \"category\": \"SAMC\", \"outcomes\": {\"en\": [\"Perform STRIDE threat modelling and remediate OWASP Top 10 vulnerabilities.\", \"Integrate automated SAST and DAST security gates into CI/CD pipelines.\"], \"ms\": [\"Melaksanakan pemodelan ancaman STRIDE dan memulihkan kelemahan OWASP Top 10.\", \"Mengintegrasikan gerbang keselamatan SAST dan DAST automatik ke dalam CI/CD.\"]}, \"signatory\": \"Hakim Rahman\", \"slt_hours\": 80, \"statement\": {\"en\": \"This SAMC is Quality-Verified. Credit 2, MQF level 6, valid until 2029-08-15.\", \"ms\": \"SAMC ini telah disahkan melalui Quality Verification. Kredit 2, tahap MQF 6, sah hingga 2029-08-15.\"}, \"assessment_basis\": \"Verified marks: STRIDE Threat Model & OWASP Remediation Lab (50%), Automated DevSecOps Pipeline Capstone (50%). Completion confirmed by the deputy dean.\"}','eyJhbGciOiJFZERTQSIsInR5cCI6IkpXVCIsImtpZCI6ImRpZDp1dGVtOmNvZGw6dmMtMjAyNi0wMSJ9..WE59TAqupLYIhVcS7W5KgoezyKd3-0VvbJtejqFOuwcHeQwTczL9Yqd37qWwynfuFKhuqqCDv3TcDKtsVtY7CA','Revoked following post-issuance employer audit of external sponsor declaration.',12,'2026-11-01 10:00:00'),(3,17,1,'issued','{\"ptj\": \"Fakulti Teknologi Maklumat Dan Komunikasi\", \"code\": \"774K8-ZC1EN\", \"name\": {\"en\": \"Database Systems\", \"ms\": \"Sistem Pangkalan Data\"}, \"claims\": {\"qv\": false, \"mqf\": null, \"credit\": 3, \"qv_until\": null}, \"cohort\": \"2027/1-DBS\", \"holder\": \"Amirul Hakim\", \"issued\": \"2026-11-24T08:38:41+00:00\", \"issuer\": \"Universiti Teknikal Malaysia Melaka\", \"number\": \"MCMS-C-2026-000017\", \"stages\": {\"en\": \"Completing this micro-credential, receiving an Academic Credit Record, depositing credit to the Academic Bank of Credit and transferring credit are separate decisions.\", \"ms\": \"Menamatkan micro-credential ini, menerima Academic Credit Record, mendepositkan kredit ke Academic Bank of Credit dan memindahkan kredit adalah keputusan yang berasingan.\"}, \"category\": \"UMC\", \"outcomes\": {\"en\": [\"Normalize database relations up to Boyce-Codd Normal Form.\", \"Construct execution-plan optimized SQL queries with composite indexes.\", \"Implement ACID transaction isolation levels and deadlock recovery.\"], \"ms\": [\"Menormalkan hubungan pangkalan data sehingga Bentuk Normal Boyce-Codd.\", \"Membina pertanyaan SQL dioptimumkan pelan pelaksanaan dengan indeks komposit.\", \"Melaksanakan tahap pengasingan transaksi ACID dan pemulihan kebuntuan.\"]}, \"signatory\": \"Hakim Rahman\", \"slt_hours\": 120, \"statement\": {\"en\": \"This is an Unbundled Micro-Credential (UMC) from BITS 1125 Databases. Completing the whole UMC carries the credit of the parent course. A module or a badge on its own is not completion and not credit.\", \"ms\": \"Ini ialah Unbundled Micro-Credential (UMC) daripada BITS 1125 Databases. Menamatkan keseluruhan UMC membawa kredit kursus induk. Satu modul atau satu lencana sahaja bukan penamatan dan bukan kredit.\"}, \"assessment_basis\": \"Verified marks: Relational Schema & BCNF Normalization Assignment (50%), SQL Query Tuning & Transaction Isolation Lab Test (50%). Completion confirmed by the deputy dean.\", \"signatory_position\": \"Deputy Dean (Academic), FTMK\", \"signatory_position_ms\": \"Timbalan Dekan (Akademik), FTMK\"}','eyJhbGciOiJFZERTQSIsInR5cCI6IkpXVCIsImtpZCI6ImRpZDp1dGVtOmNvZGw6dmMtMjAyNi0wMSJ9..GEcS-iNl4dnw-BE1qIKIsak4Igt7nXiBySvhxyYPvgyf1bIObUxeB5UkAtDG5vgCyJRvDd-k91esHOSqNIGIBg',NULL,10,'2026-11-24 08:38:41');
