INSERT INTO `feedback_responses` VALUES (1,1,1,'{\"ease\": 5, \"admin\": 4, \"depth\": 4, \"clarity\": 5, \"content\": 5, \"support\": 5, \"fairness\": 5, \"lecturer\": 5, \"platform\": 5, \"practice\": 5, \"workload\": 4, \"recommend\": 5, \"relevance\": 5, \"activities\": 5, \"assessment\": 5, \"reliability\": 5, \"feedback_quality\": 4}','Exceptional course. The Kubernetes deployment project directly improved my daily work at my company.','2026-09-07 01:42:39'),(2,1,2,'{\"ease\": 4, \"admin\": 3, \"depth\": 3, \"clarity\": 4, \"content\": 4, \"support\": 4, \"fairness\": 4, \"lecturer\": 4, \"platform\": 4, \"practice\": 4, \"workload\": 3, \"recommend\": 4, \"relevance\": 4, \"activities\": 4, \"assessment\": 4, \"reliability\": 4, \"feedback_quality\": 3}','Very comprehensive curriculum, appreciated the weekly live consultation clinics.','2026-09-08 01:42:39'),(3,12,9,'{\"ease\": 5, \"admin\": 4, \"depth\": 4, \"clarity\": 5, \"content\": 5, \"support\": 5, \"fairness\": 5, \"lecturer\": 5, \"platform\": 5, \"practice\": 5, \"workload\": 4, \"recommend\": 5, \"relevance\": 5, \"activities\": 5, \"assessment\": 5, \"reliability\": 5, \"feedback_quality\": 4}','Clear explanation of tree balancing and graph heuristics; lab test bench was very helpful.','2026-08-21 10:00:00'),(4,12,10,'{\"ease\": 4, \"admin\": 3, \"depth\": 3, \"clarity\": 4, \"content\": 4, \"support\": 4, \"fairness\": 4, \"lecturer\": 4, \"platform\": 4, \"practice\": 4, \"workload\": 3, \"recommend\": 4, \"relevance\": 4, \"activities\": 4, \"assessment\": 4, \"reliability\": 4, \"feedback_quality\": 3}','Great course structure, though week 6 graph assignment was challenging.','2026-08-21 14:00:00'),(5,12,11,'{\"ease\": 4, \"admin\": 3, \"depth\": 3, \"clarity\": 4, \"content\": 4, \"support\": 4, \"fairness\": 4, \"lecturer\": 4, \"platform\": 4, \"practice\": 4, \"workload\": 3, \"recommend\": 4, \"relevance\": 4, \"activities\": 4, \"assessment\": 4, \"reliability\": 4, \"feedback_quality\": 3}','Well-paced video lectures and responsive Teams clinic.','2026-08-22 09:00:00'),(6,12,12,'{\"ease\": 5, \"admin\": 4, \"depth\": 4, \"clarity\": 5, \"content\": 5, \"support\": 5, \"fairness\": 5, \"lecturer\": 5, \"platform\": 5, \"practice\": 5, \"workload\": 4, \"recommend\": 5, \"relevance\": 5, \"activities\": 5, \"assessment\": 5, \"reliability\": 5, \"feedback_quality\": 4}','Directly prepared me for technical coding interviews.','2026-08-22 11:00:00'),(7,13,13,'{\"ease\": 5, \"admin\": 4, \"depth\": 4, \"clarity\": 5, \"content\": 5, \"support\": 5, \"fairness\": 5, \"lecturer\": 5, \"platform\": 5, \"practice\": 5, \"workload\": 4, \"recommend\": 5, \"relevance\": 5, \"activities\": 5, \"assessment\": 5, \"reliability\": 5, \"feedback_quality\": 4}','Hands-on GitLab SAST/DAST pipeline labs are industry grade.','2026-10-21 10:00:00'),(8,13,14,'{\"ease\": 5, \"admin\": 4, \"depth\": 4, \"clarity\": 5, \"content\": 5, \"support\": 5, \"fairness\": 5, \"lecturer\": 5, \"platform\": 5, \"practice\": 5, \"workload\": 4, \"recommend\": 5, \"relevance\": 5, \"activities\": 5, \"assessment\": 5, \"reliability\": 5, \"feedback_quality\": 4}','STRIDE threat modelling templates were immediately useful at work.','2026-10-21 15:00:00'),(9,13,16,'{\"ease\": 3, \"admin\": 3, \"depth\": 3, \"clarity\": 3, \"content\": 3, \"support\": 3, \"fairness\": 3, \"lecturer\": 3, \"platform\": 3, \"practice\": 3, \"workload\": 3, \"recommend\": 3, \"relevance\": 3, \"activities\": 3, \"assessment\": 3, \"reliability\": 3, \"feedback_quality\": 3}','Module 2 DAST container setup required more memory than my laptop had.','2026-10-22 09:00:00'),(10,14,17,'{\"ease\": 5, \"admin\": 4, \"depth\": 4, \"clarity\": 5, \"content\": 5, \"support\": 5, \"fairness\": 5, \"lecturer\": 5, \"platform\": 5, \"practice\": 5, \"workload\": 4, \"recommend\": 5, \"relevance\": 5, \"activities\": 5, \"assessment\": 5, \"reliability\": 5, \"feedback_quality\": 4}','SOLID refactoring exercises really sharpened my Java architecture skills.','2026-10-01 10:00:00'),(11,15,19,'{\"ease\": 5, \"admin\": 4, \"depth\": 4, \"clarity\": 5, \"content\": 5, \"support\": 5, \"fairness\": 5, \"lecturer\": 5, \"platform\": 5, \"practice\": 5, \"workload\": 4, \"recommend\": 5, \"relevance\": 5, \"activities\": 5, \"assessment\": 5, \"reliability\": 5, \"feedback_quality\": 4}','Executive mentoring and venture valuation rubric were top notch.','2026-10-03 10:00:00'),(12,16,20,'{\"ease\": 5, \"admin\": 4, \"depth\": 4, \"clarity\": 5, \"content\": 5, \"support\": 5, \"fairness\": 5, \"lecturer\": 5, \"platform\": 5, \"practice\": 5, \"workload\": 4, \"recommend\": 5, \"relevance\": 5, \"activities\": 5, \"assessment\": 5, \"reliability\": 5, \"feedback_quality\": 4}','Loved the RAG and transformer fine-tuning notebooks.','2026-10-27 10:00:00'),(13,21,39,'{\"ease\": 4, \"admin\": 4, \"depth\": 5, \"clarity\": 4, \"content\": 5, \"support\": 5, \"fairness\": 5, \"lecturer\": 5, \"platform\": 4, \"practice\": 5, \"workload\": 4, \"recommend\": 5, \"relevance\": 5, \"activities\": 4, \"assessment\": 5, \"reliability\": 4, \"feedback_quality\": 5}','Great hands-on Docker labs. Kubernetes networking lab could use an extra troubleshooting walkthrough.','2026-11-18 11:00:00'),(14,21,40,'{\"ease\": 4, \"admin\": 4, \"depth\": 5, \"clarity\": 4, \"content\": 5, \"support\": 5, \"fairness\": 5, \"lecturer\": 5, \"platform\": 3, \"practice\": 5, \"workload\": 4, \"recommend\": 5, \"relevance\": 5, \"activities\": 4, \"assessment\": 5, \"reliability\": 3, \"feedback_quality\": 5}','Very relevant to industry work. Sandbox provisioning was slightly slow during week 5 peak hours.','2026-11-18 11:00:00'),(15,21,41,'{\"ease\": 4, \"admin\": 4, \"depth\": 5, \"clarity\": 4, \"content\": 5, \"support\": 5, \"fairness\": 5, \"lecturer\": 5, \"platform\": 4, \"practice\": 5, \"workload\": 4, \"recommend\": 5, \"relevance\": 5, \"activities\": 4, \"assessment\": 5, \"reliability\": 4, \"feedback_quality\": 5}','Clear rubric and helpful lecturer feedback. Adding a short Helm chart cheat-sheet would help beginners.','2026-11-18 11:00:00');
