INSERT INTO `learning_outcomes` VALUES (1,1,'LO1','Implement contiguous and linked data structures in software.','Melaksanakan struktur data bersebelahan dan berpaut dalam perisian.',1,1),(2,1,'LO2','Apply tree traversal and graph traversal algorithms to solve complex searching problems.','Mengaplikasikan algoritma lintasan pokok dan graf untuk menyelesaikan masalah carian.',2,2),(3,1,'LO3','Evaluate asymptotic time and memory complexity of computer algorithms.','Menilai kerumitan masa dan ingatan asimtotik algoritma komputer.',3,3),(4,2,'LO1','Package cloud-ready container images following OCI specifications.','Membungkus imej kontena sedia awan mengikut spesifikasi OCI.',1,NULL),(5,2,'LO2','Deploy resilient microservices workloads onto Kubernetes clusters.','Menyebarkan beban kerja mikroperkhidmatan ke kluster Kubernetes.',2,NULL),(6,3,'LO1','Demonstrate situational leadership and effective team negotiation.','Menunjukkan kepimpinan situasi dan rundingan pasukan yang berkesan.',1,NULL),(7,4,'LO1','Detect security anomalies and execute initial response playbook.','Mengesan anomali keselamatan dan melaksanakan buku panduan tindak balas awal.',1,NULL),(8,5,'LO1','Normalize database relations up to Boyce-Codd Normal Form.','Menormalkan hubungan pangkalan data sehingga Bentuk Normal Boyce-Codd.',1,1),(9,6,'LO1','Build predictive linear models using Python and statistical toolkits.','Membina model linear ramalan menggunakan kit alat statistik Python.',1,NULL),(10,7,'LO1','Apply DMAIC metrics to identify and eliminate manufacturing bottlenecks.','Mengaplikasikan metrik DMAIC untuk mengenal pasti dan menghapuskan kekangan.',1,NULL),(11,13,'LO1','Analyze complex multi-loop circuits using network theorems.','Menganalisis litar kompleks menggunakan teorem rangkaian.',1,1),(12,14,'LO1','Calculate internal reactions and stresses in mechanical structures.','Mengira tindak balas dalaman dan tegasan dalam struktur mekanikal.',1,1),(13,15,'LO1','Design low-power wireless sensor communication protocols.','Mereka bentuk protokol komunikasi sensor wayarles kuasa rendah.',1,1),(14,16,'LO1','Evaluate machining tolerances and surface roughness against standards.','Menilai toleransi pemesinan dan kekasaran permukaan mengikut piawaian.',1,1),(15,17,'LO1','Execute statistical exploratory analyses on high-dimensional datasets.','Melaksanakan analisis penerokaan statistik ke atas set data.',1,1),(16,5,'LO2','Construct execution-plan optimized SQL queries with composite indexes.','Membina pertanyaan SQL dioptimumkan pelan pelaksanaan dengan indeks komposit.',2,2),(17,5,'LO3','Implement ACID transaction isolation levels and deadlock recovery.','Melaksanakan tahap pengasingan transaksi ACID dan pemulihan kebuntuan.',3,3),(18,8,'LO1','Implement memory-efficient linear and hash-based data structures.','Melaksanakan struktur data linear dan berasaskan cincangan yang cekap memori.',1,1),(19,8,'LO2','Solve shortest-path and spanning-tree network problems.','Menyelesaikan masalah rangkaian laluan terpendek dan pepohon merentang.',2,2),(20,9,'LO1','Perform STRIDE threat modelling and remediate OWASP Top 10 vulnerabilities.','Melaksanakan pemodelan ancaman STRIDE dan memulihkan kelemahan OWASP Top 10.',1,NULL),(21,9,'LO2','Integrate automated SAST and DAST security gates into CI/CD pipelines.','Mengintegrasikan gerbang keselamatan SAST dan DAST automatik ke dalam CI/CD.',2,NULL),(22,10,'LO1','Formulate linear and integer optimization models for resource allocation.','Merumuskan model pengoptimuman linear dan integer untuk peruntukan sumber.',1,NULL),(23,11,'LO1','Enforce Kubernetes admission controller and runtime security policies.','Menguatkuasakan pengawal kemasukan Kubernetes dan polisi keselamatan masa jalan.',1,NULL),(24,12,'LO1','Design versioned OpenAPI contracts and OAuth2/OIDC gateway policies.','Mereka bentuk kontrak OpenAPI berversi dan polisi gerbang OAuth2/OIDC.',1,NULL),(25,18,'LO1','Design modular object-oriented software adhering to SOLID principles.','Mereka bentuk perisian berorientasikan objek modular mematuhi prinsip SOLID.',1,1),(26,18,'LO2','Verify software reliability using automated JUnit test suites.','Mengesahkan kebolehpercayaan perisian menggunakan suit ujian JUnit automatik.',2,2),(27,19,'LO1','Simulate grid-synchronized PWM inverter controllers under fault conditions.','Mensimulasikan pengawal penyongsang PWM disegerakkan grid di bawah keadaan kerosakan.',1,NULL),(28,20,'LO1','Conduct industrial thermal energy audits and quantify waste-heat recovery.','Menjalankan audit tenaga terma industri dan mengukur pemulihan haba sisa.',1,1),(29,21,'LO1','Validate technology business models and formulate go-to-market strategies.','Mengesahkan model perniagaan teknologi dan merumuskan strategi pasaran.',1,1),(30,21,'LO2','Construct financial projections and defend an investment-ready venture pitch.','Membina unjuran kewangan dan mempertahankan pembentangan usaha niaga sedia pelaburan.',2,2),(31,22,'LO1','Synthesize and verify synchronous digital IPs on FPGA hardware.','Mensintesis dan mengesahkan IP digital segerak pada perkakasan FPGA.',1,NULL),(32,23,'LO1','Synchronize PLC ladder logic with a 3D digital twin workcell.','Menyegerakkan logik tangga PLC dengan sel kerja kembar digital 3D.',1,NULL),(33,24,'LO1','Train and evaluate deep neural network architectures on domain datasets.','Melatih dan menilai seni bina rangkaian neural mendalam pada set data domain.',1,1),(34,24,'LO2','Fine-tune transformer models and deploy retrieval-augmented generation (RAG).','Menala halus model transformer dan menyebarkan penjanaan dipertingkat carian (RAG).',2,2),(35,28,'LO1','Design modular object-oriented software adhering to SOLID principles.','Mereka bentuk perisian berorientasikan objek modular mematuhi prinsip SOLID.',1,NULL),(36,28,'LO2','Verify software reliability using automated JUnit test suites.','Mengesahkan kebolehpercayaan perisian menggunakan suit ujian JUnit automatik.',2,NULL),(37,29,'LO1','Configure secure MQTT sensor telemetry pipelines between industrial edge nodes and time-series brokers.','Mengkonfigurasi saluran telemetri penderia MQTT yang selamat antara nod pinggir industri dan broker siri masa.',1,NULL),(38,29,'LO2','Implement lightweight edge analytics models to detect equipment anomalies in real-time telemetry streams.','Melaksanakan model analitik pinggir ringan bagi mengesan anomali peralatan dalam aliran telemetri masa nyata.',2,NULL),(39,29,'LO3','Evaluate edge deployment reliability, latency, and security trade-offs for a manufacturing use case.','Menilai kebolehpercayaan, kependaman dan keselamatan pelaksanaan pinggir bagi kes guna pembuatan.',3,NULL),(40,29,'LO4',NULL,NULL,4,NULL),(41,31,'LO1','Design normalized relational database schemas (up to 3NF) that satisfy enterprise integrity constraints.','Mereka bentuk skema pangkalan data hubungan ternormal (sehingga 3NF) yang memenuhi kekangan integriti perusahaan.',1,1),(42,31,'LO2','Construct complex analytical SQL queries, views, and indexing strategies to retrieve operational datasets efficiently.','Membina pertanyaan SQL analitik kompleks, paparan, dan strategi pengindeksan untuk mendapatkan set data operasi secara cekap.',2,2),(43,31,'LO3','Evaluate transaction isolation levels, concurrency locks, and query execution plans for high-throughput database workloads.','Menilai tahap pengasingan transaksi, kunci keserentakan, dan pelan pelaksanaan pertanyaan bagi beban kerja pangkalan data berdaya pemprosesan tinggi.',3,3),(44,32,'LO1','Design structured prompt templates and retrieval-augmented generation (RAG) pipelines for domain-specific knowledge bases.','Mereka bentuk templat prom berstruktur dan saluran penjanaan diperkaya dapatan semula (RAG) bagi pangkalan pengetahuan khusus domain.',1,NULL),(45,32,'LO2','Implement reliable LLM API integrations featuring JSON schema validation, automated evaluation suites, and graceful fallback controls.','Melaksanakan integrasi API LLM yang boleh dipercayai dengan pengesahan skema JSON, suit penilaian automatik, dan kawalan sandaran.',2,NULL),(46,32,'LO3','Evaluate data privacy, hallucination mitigation, latency, and inference cost governance in production AI software services.','Menilai privasi data, pengurangan halusinasi, kependaman, dan tadbir urus kos inferens dalam perkhidmatan perisian AI produksi.',3,NULL),(47,33,'LO1','Identify common enterprise phishing, credential theft, and ransomware attack vectors across hybrid workplaces.','Mengenal pasti vektor serangan pancingan data, kecurian kelayakan, dan perisian tebusan yang lazim di tempat kerja hibrid.',1,NULL),(48,33,'LO2','Execute a structured first-response containment and incident escalation checklist during a simulated security breach.','Melaksanakan senarai semak pembendungan tindak balas awal dan eskalasi insiden berstruktur semasa simulasi pelanggaran keselamatan.',2,NULL);
/*!40000 ALTER TABLE `learning_outcomes` ENABLE KEYS */;
UNLOCK TABLES;

