INSERT INTO `template_versions` VALUES (1,1,'en',1,'Your MCMS role changed','Hello {name}, you now hold the role {role} ({scope}) from {from}. Reason: {reason}.',NULL,'First version','2025-11-05 04:50:46'),(2,1,'ms',1,'Peranan MCMS anda telah berubah','Salam {name}, anda kini memegang peranan {role} ({scope}) mulai {from}. Sebab: {reason}.',NULL,'Keluaran awal templat','2025-11-05 04:50:46'),(3,2,'en',1,'Your MCMS role ended','Hello {name}, your role {role} has ended. Reason: {reason}.',NULL,'First version','2025-11-05 04:50:46'),(4,2,'ms',1,'Peranan MCMS anda telah tamat','Salam {name}, peranan {role} anda telah tamat. Sebab: {reason}.',NULL,'Keluaran awal templat','2025-11-05 04:50:46'),(5,3,'en',1,'Your MCMS account is deactivated','Hello {name}, your account has been deactivated. Reason: {reason}. Your records are kept.',NULL,'First version','2025-11-05 04:50:46'),(6,3,'ms',1,'Akaun MCMS anda dinyahaktifkan','Salam {name}, akaun anda telah dinyahaktifkan. Sebab: {reason}. Rekod anda dikekalkan.',NULL,'Keluaran awal templat','2025-11-05 04:50:46'),(7,4,'en',1,'Your MCMS account is active again','Hello {name}, your account is active again.',NULL,'First version','2025-11-05 04:50:46'),(8,4,'ms',1,'Akaun MCMS anda aktif semula','Salam {name}, akaun anda aktif semula.',NULL,'Keluaran awal templat','2025-11-05 04:50:46'),(9,5,'en',1,'A decision was recorded on {item}','Hello {name}, the decision on {item} is: {decision}.',NULL,'First version','2025-11-05 04:50:46'),(10,5,'ms',1,'Keputusan telah direkodkan bagi {item}','Salam {name}, keputusan bagi {item} ialah: {decision}.',NULL,'Keluaran awal templat','2025-11-05 04:50:46'),(11,6,'en',1,'Proposal submitted: {title}','Hello {name}, {owner} submitted the proposal \"{title}\". Please assign reviewers.',NULL,'First version','2025-11-05 04:50:46'),(12,6,'ms',1,'Cadangan dihantar: {title}','Salam {name}, {owner} telah menghantar cadangan \"{title}\". Sila tetapkan penilai.',NULL,'Keluaran awal templat','2025-11-05 04:50:46'),(13,7,'en',1,'Review requested: {title}','Hello {name}, you are asked to review \"{title}\" by {due}. Declare any conflict of interest before you open it.',NULL,'First version','2025-11-05 04:50:46'),(14,7,'ms',1,'Permintaan penilaian: {title}','Salam {name}, anda diminta menilai \"{title}\" sebelum {due}. Isytiharkan sebarang konflik kepentingan sebelum membukanya.',NULL,'Keluaran awal templat','2025-11-05 04:50:46'),(15,8,'en',1,'Reviewer declined: {title}','Hello {name}, {reviewer} declared a conflict of interest and left the review of \"{title}\". Please assign another reviewer.',NULL,'First version','2025-11-05 04:50:46'),(16,8,'ms',1,'Penilai menarik diri: {title}','Salam {name}, {reviewer} mengisytiharkan konflik kepentingan dan menarik diri daripada penilaian \"{title}\". Sila tetapkan penilai lain.',NULL,'Keluaran awal templat','2025-11-05 04:50:46'),(17,9,'en',1,'Review submitted: {title}','Hello {name}, {reviewer} submitted a review of \"{title}\": {recommendation}.',NULL,'First version','2025-11-05 04:50:46'),(18,9,'ms',1,'Penilaian dihantar: {title}','Salam {name}, {reviewer} telah menghantar penilaian \"{title}\": {recommendation}.',NULL,'Keluaran awal templat','2025-11-05 04:50:46'),(19,10,'en',1,'Returned for amendment: {title}','Hello {name}, \"{title}\" is returned for amendment. Reason: {reason}. It is unlocked.',NULL,'First version','2025-11-05 04:50:46'),(20,10,'ms',1,'Dikembalikan untuk pindaan: {title}','Salam {name}, \"{title}\" dikembalikan untuk pindaan. Sebab: {reason}. Ia dibuka semula.',NULL,'Keluaran awal templat','2025-11-05 04:50:46'),(21,11,'en',1,'Endorsed: {title}','Hello {name}, \"{title}\" is endorsed and waits for the Senate decision.',NULL,'First version','2025-11-05 04:50:46'),(22,11,'ms',1,'Disokong: {title}','Salam {name}, \"{title}\" telah disokong dan menunggu keputusan Senat.',NULL,'Keluaran awal templat','2025-11-05 04:50:46'),(23,12,'en',1,'Minor change recorded: {title}','Hello {name}, {owner} recorded a minor change to \"{title}\": {summary}. Please acknowledge it.',NULL,'First version','2025-11-05 04:50:46'),(24,12,'ms',1,'Perubahan kecil direkodkan: {title}','Salam {name}, {owner} merekodkan perubahan kecil bagi \"{title}\": {summary}. Sila akui.',NULL,'Keluaran awal templat','2025-11-05 04:50:46'),(25,13,'en',1,'Please pay to complete your registration: {title}','Hello {name}, your place in \"{title}\" is held while you pay RM {fee}. Open \"Registrations and payments\" to pay.',NULL,'First version','2025-11-05 04:50:46'),(26,13,'ms',1,'Sila bayar untuk melengkapkan pendaftaran: {title}','Salam {name}, tempat anda dalam \"{title}\" dikekalkan sementara anda membayar RM {fee}. Buka \"Pendaftaran dan bayaran\" untuk membayar.',NULL,'Keluaran awal templat','2025-11-05 04:50:46'),(27,14,'en',1,'Payment received: {reference}','Hello {name}, we received RM {amount} for registration {reference} (payment reference {payment}).',NULL,'First version','2025-11-05 04:50:46'),(28,14,'ms',1,'Bayaran diterima: {reference}','Salam {name}, kami menerima RM {amount} untuk pendaftaran {reference} (rujukan bayaran {payment}).',NULL,'Keluaran awal templat','2025-11-05 04:50:46'),(29,15,'en',1,'You are enrolled: {title}','Hello {name}, you are enrolled in \"{title}\" (ID {reference}). The cohort starts on {start}. Open the learning platform course: {platform}.',NULL,'First version','2025-11-05 04:50:46'),(30,15,'ms',1,'Anda telah didaftarkan: {title}','Salam {name}, anda telah didaftarkan dalam \"{title}\" (ID {reference}). Kohort bermula pada {start}. Buka kursus platform pembelajaran: {platform}.',NULL,'Keluaran awal templat','2025-11-05 04:50:46'),(31,16,'en',1,'You have withdrawn: {title}','Hello {name}, you have withdrawn from \"{title}\". Refunds are handled outside MCMS: ask the CODL office.',NULL,'First version','2025-11-05 04:50:46'),(32,16,'ms',1,'Anda telah menarik diri: {title}','Salam {name}, anda telah menarik diri daripada \"{title}\". Bayaran balik diuruskan di luar MCMS: hubungi pejabat CODL.',NULL,'Keluaran awal templat','2025-11-05 04:50:46'),(33,17,'en',1,'A change to {title}','Hello {name}, version {version} of \"{title}\" takes effect on {date}. What this means for you: {rule}.',NULL,'First version','2025-11-05 04:50:46'),(34,17,'ms',1,'Perubahan pada {title}','Salam {name}, versi {version} bagi \"{title}\" berkuat kuasa pada {date}. Maksudnya bagi anda: {rule}.',NULL,'Keluaran awal templat','2025-11-05 04:50:46'),(35,18,'en',1,'UCreds {kind} staged: {title}','Hello {name}, {staged} rows of the UCreds {kind} file for \"{title}\" were staged. {detail} Complete any missing marks on the cohort results page.',NULL,'First version','2025-11-05 04:50:46'),(36,18,'ms',1,'Fail UCreds disediakan: {title}','Salam {name}, {staged} baris fail UCreds {kind} bagi \"{title}\" telah disediakan. {detail} Lengkapkan markah yang tiada pada halaman keputusan kohort.',NULL,'Keluaran awal templat','2025-11-05 04:50:46'),(37,19,'en',1,'Your results are verified: {title}','Hello {name}, your results for \"{title}\" are verified. Open \"My results\" to see them.',NULL,'First version','2025-11-05 04:50:46'),(38,19,'ms',1,'Keputusan anda telah disahkan: {title}','Salam {name}, keputusan anda bagi \"{title}\" telah disahkan. Buka \"Keputusan saya\" untuk melihatnya.',NULL,'Keluaran awal templat','2025-11-05 04:50:46'),(39,20,'en',1,'Completion confirmed: {title}','Hello {name}, the deputy dean confirmed that you completed \"{title}\". Your certificate or Digital Credential is issued after this confirmation.',NULL,'First version','2025-11-05 04:50:46'),(40,20,'ms',1,'Penamatan disahkan: {title}','Salam {name}, timbalan dekan telah mengesahkan bahawa anda menamatkan \"{title}\". Sijil atau Digital Credential anda dikeluarkan selepas pengesahan ini.',NULL,'Keluaran awal templat','2025-11-05 04:50:46'),(41,21,'en',1,NULL,'I agree that UTeM may send my Academic Credit Record to the Academic Bank of Credit (ABC) for storage. A deposit is storage of a credit record only. It is not a credit transfer and does not mean any programme accepts the credit. I can decline or postpone and give consent later.',NULL,'First version','2025-11-05 04:50:46'),(42,21,'ms',1,NULL,'Saya bersetuju UTeM menghantar Rekod Kredit Akademik saya kepada Akaun Bank Kredit (ABC) untuk disimpan. Deposit ialah penyimpanan rekod kredit sahaja. Ia bukan pindahan kredit dan tidak bermakna mana-mana program menerima kredit tersebut. Saya boleh menolak atau menangguhkan dan memberi persetujuan kemudian.',NULL,'Keluaran awal templat','2025-11-05 04:50:46'),(43,22,'en',1,'Your Academic Credit Record is ready: {title}','Hello {name}, your Academic Credit Record for \"{title}\" is confirmed. Open \"Credit ledger and ABC\" to give, decline or postpone consent to deposit it. Nothing is deposited without your consent.',NULL,'First version','2025-11-05 04:50:46'),(44,22,'ms',1,'Rekod Kredit Akademik anda sedia: {title}','Salam {name}, Rekod Kredit Akademik anda bagi \"{title}\" telah disahkan. Buka \"Lejar kredit dan ABC\" untuk memberi, menolak atau menangguhkan persetujuan deposit. Tiada apa didepositkan tanpa persetujuan anda.',NULL,'Keluaran awal templat','2025-11-05 04:50:46'),(45,23,'en',1,'Your credit is deposited: {title}','Hello {name}, your Academic Credit Record for \"{title}\" is deposited in ABC and the credit is available until {date}. A deposit is storage only and is not a credit transfer.',NULL,'First version','2025-11-05 04:50:46'),(46,23,'ms',1,'Kredit anda didepositkan: {title}','Salam {name}, Rekod Kredit Akademik anda bagi \"{title}\" telah didepositkan di ABC dan kredit tersedia sehingga {date}. Deposit ialah penyimpanan sahaja dan bukan pindahan kredit.',NULL,'Keluaran awal templat','2025-11-05 04:50:46'),(47,24,'en',1,'Your credit ends in {days} days: {title}','Hello {name}, the credit from \"{title}\" is valid until {date}, in {days} days. After that it shows as Expired for transfer purposes. Your record is kept.',NULL,'First version','2025-11-05 04:50:46'),(48,24,'ms',1,'Kredit anda tamat dalam {days} hari: {title}','Salam {name}, kredit daripada \"{title}\" sah sehingga {date}, dalam {days} hari. Selepas itu ia dipaparkan Tamat Tempoh untuk tujuan pindahan. Rekod anda kekal.',NULL,'Keluaran awal templat','2025-11-05 04:50:46'),(49,25,'en',1,'Your credit has expired: {title}','Hello {name}, the credit from \"{title}\" expired on {date}. Your Academic Credit Record is kept. A transfer request that uses it is flagged for re-evaluation.',NULL,'First version','2025-11-05 04:50:46'),(50,25,'ms',1,'Kredit anda telah tamat tempoh: {title}','Salam {name}, kredit daripada \"{title}\" tamat tempoh pada {date}. Rekod Kredit Akademik anda kekal. Permohonan pindahan yang menggunakannya ditanda untuk penilaian semula.',NULL,'Keluaran awal templat','2025-11-05 04:50:46'),(51,26,'en',1,'Credit transfer {ref}: {outcome}','Hello {name}, the decision on your credit transfer application {ref} is: {outcome}. Open \"Credit transfer\" for the details. A transfer decision is separate from admission to the programme.',NULL,'First version','2025-11-05 04:50:46'),(52,26,'ms',1,'Pindahan kredit {ref}: {outcome}','Salam {name}, keputusan permohonan pindahan kredit anda {ref} ialah: {outcome}. Buka \"Pindahan kredit\" untuk butiran. Keputusan pindahan adalah berasingan daripada kemasukan ke program.',NULL,'Keluaran awal templat','2025-11-05 04:50:46'),(53,27,'en',1,'More evidence needed: {ref}','Hello {name}, the evaluator needs more evidence for your credit transfer application {ref}: {request}',NULL,'First version','2025-11-05 04:50:46'),(54,27,'ms',1,'Bukti tambahan diperlukan: {ref}','Salam {name}, penilai memerlukan bukti tambahan bagi permohonan pindahan kredit anda {ref}: {request}',NULL,'Keluaran awal templat','2025-11-05 04:50:46'),(55,28,'en',1,'Your degree plan {ref}: {decision}','Hello {name}, the decision on your stackable degree plan {ref} is: {decision}. A plan is advice. It is not admission, a credit transfer or an award.',NULL,'First version','2025-11-05 04:50:46'),(56,28,'ms',1,'Pelan ijazah anda {ref}: {decision}','Salam {name}, keputusan pelan ijazah berperingkat anda {ref} ialah: {decision}. Pelan ialah nasihat. Ia bukan kemasukan, pindahan kredit atau anugerah.',NULL,'Keluaran awal templat','2025-11-05 04:50:46'),(57,29,'en',1,'Your cohort was {kind}: {title}','Hello {name}, the cohort \"{title}\" was {kind} from {date}. Reason: {reason}. What happens to you: {plan}. Achievements, credentials and your Academic Credit Record you already earned stay valid.',NULL,'First version','2025-11-05 04:50:46'),(58,29,'ms',1,'Kohort anda {kind}: {title}','Salam {name}, kohort \"{title}\" telah {kind} mulai {date}. Sebab: {reason}. Apa yang berlaku kepada anda: {plan}. Pencapaian, kredensial dan Rekod Kredit Akademik yang telah anda peroleh kekal sah.',NULL,'Keluaran awal templat','2025-11-05 04:50:46'),(59,30,'en',1,'Periodic review due on {date}: {title}','Hello {name}, the periodic review of \"{title}\" is due on {date}. Record its outcome in Quality review.',NULL,'First version','2025-11-05 04:50:46'),(60,30,'ms',1,'Semakan berkala pada {date}: {title}','Salam {name}, semakan berkala bagi \"{title}\" perlu dibuat pada {date}. Rekodkan hasilnya dalam Semakan kualiti.',NULL,'Keluaran awal templat','2025-11-05 04:50:46'),(61,31,'en',1,'A correction affects your record','Hello {name}, a mismatch in your records was corrected. What was found: {what} What was done: {action} The original is kept in the record and your earlier achievements stay valid.',NULL,'First version','2025-11-05 04:50:46'),(62,31,'ms',1,'Pembetulan melibatkan rekod anda','Salam {name}, ketidakpadanan dalam rekod anda telah dibetulkan. Apa yang ditemui: {what} Apa yang dilakukan: {action} Rekod asal disimpan dan pencapaian anda yang terdahulu kekal sah.',NULL,'Keluaran awal templat','2025-11-05 04:50:46'),(63,32,'en',1,'Quality Verification ends in {days} days: {title}','Hello {name}, the Quality Verification of \"{title}\" ends on {date}, in {days} days. Prepare a new cycle so the credit and level stay in the catalogue.',NULL,'First version','2025-11-05 04:50:46'),(64,32,'ms',1,'Pengesahan Kualiti tamat dalam {days} hari: {title}','Salam {name}, Pengesahan Kualiti bagi \"{title}\" tamat pada {date}, dalam {days} hari. Sediakan kitaran baharu supaya kredit dan tahap kekal dalam katalog.',NULL,'Keluaran awal templat','2025-11-05 04:50:46'),(65,33,'en',1,'Quality Verification ended: {title}','Hello {name}, the Quality Verification of \"{title}\" ended. Reason: {why}. The credit and level are no longer shown for new cohorts and new credentials. Credentials already earned stay.',NULL,'First version','2025-11-05 04:50:46'),(66,33,'ms',1,'Pengesahan Kualiti tamat: {title}','Salam {name}, Pengesahan Kualiti bagi \"{title}\" telah tamat. Sebab: {why}. Kredit dan tahap tidak lagi dipaparkan untuk kohort dan kredensial baharu. Kredensial yang telah diperoleh kekal.',NULL,'Keluaran awal templat','2025-11-05 04:50:46'),(67,34,'en',1,'Time to finish: {title}','Hello {name}, you have until {date} to complete all modules of \"{title}\".',NULL,'First version','2025-11-05 04:50:46'),(68,34,'ms',1,'Masa untuk menamatkan: {title}','Salam {name}, anda mempunyai sehingga {date} untuk menamatkan semua modul \"{title}\".',NULL,'Keluaran awal templat','2025-11-05 04:50:46'),(69,35,'en',1,'Your credential is issued: {title}','Hello {name}, your certificate and Digital Credential for \"{title}\" are issued (number {number}). Open \"Credentials\" to see, share and download them.',NULL,'First version','2025-11-05 04:50:46'),(70,35,'ms',1,'Kredensial anda dikeluarkan: {title}','Salam {name}, sijil dan Digital Credential anda bagi \"{title}\" telah dikeluarkan (nombor {number}). Buka \"Kredensial\" untuk melihat, berkongsi dan memuat turunnya.',NULL,'Keluaran awal templat','2025-11-05 04:50:46'),(71,36,'en',1,'Your credential was corrected: {number}','Hello {name}, credential {number} was corrected. Reason: {reason}. The original is kept and the public link shows Corrected.',NULL,'First version','2025-11-05 04:50:46'),(72,36,'ms',1,'Kredensial anda telah dibetulkan: {number}','Salam {name}, kredensial {number} telah dibetulkan. Sebab: {reason}. Yang asal disimpan dan pautan awam menunjukkan Dibetulkan.',NULL,'Keluaran awal templat','2025-11-05 04:50:46'),(73,37,'en',1,'Your credential was replaced: {number}','Hello {name}, credential {number} was replaced by a new one. Reason: {reason}. Share the new link.',NULL,'First version','2025-11-05 04:50:46'),(74,37,'ms',1,'Kredensial anda telah diganti: {number}','Salam {name}, kredensial {number} telah diganti dengan yang baharu. Sebab: {reason}. Kongsikan pautan baharu.',NULL,'Keluaran awal templat','2025-11-05 04:50:46'),(75,38,'en',1,'Your credential was revoked: {number}','Hello {name}, credential {number} was revoked. Reason: {reason}.',NULL,'First version','2025-11-05 04:50:46'),(76,38,'ms',1,'Kredensial anda telah dibatalkan: {number}','Salam {name}, kredensial {number} telah dibatalkan. Sebab: {reason}.',NULL,'Keluaran awal templat','2025-11-05 04:50:46'),(77,39,'en',1,'Registration cancelled: {title}','Hello {name}, your registration for \"{title}\" is cancelled. {reason}',NULL,'First version','2025-11-05 04:50:46'),(78,39,'ms',1,'Pendaftaran dibatalkan: {title}','Salam {name}, pendaftaran anda untuk \"{title}\" dibatalkan. {reason}',NULL,'Keluaran awal templat','2025-11-05 04:50:46'),(79,40,'en',1,NULL,'This is an Unbundled Micro-Credential (UMC) from {parent}. Completing the whole UMC carries the credit of the parent course. A module or a badge on its own is not completion and not credit.',NULL,'First version','2025-11-05 04:50:46'),(80,40,'ms',1,NULL,'Ini ialah Unbundled Micro-Credential (UMC) daripada {parent}. Menamatkan keseluruhan UMC membawa kredit kursus induk. Satu modul atau satu lencana sahaja bukan penamatan dan bukan kredit.',NULL,'Keluaran awal templat','2025-11-05 04:50:46'),(81,41,'en',1,NULL,'This is a Standalone Micro-Credential (SAMC). It carries no credit value and no MQF level unless it is Quality-Verified and the verification is valid.',NULL,'First version','2025-11-05 04:50:46'),(82,41,'ms',1,NULL,'Ini ialah Standalone Micro-Credential (SAMC). Ia tidak membawa nilai kredit atau tahap MQF melainkan telah disahkan melalui Quality Verification dan pengesahan itu masih sah.',NULL,'Keluaran awal templat','2025-11-05 04:50:46'),(83,42,'en',1,NULL,'This SAMC is Quality-Verified. Credit {credit}, MQF level {mqf}, valid until {until}.',NULL,'First version','2025-11-05 04:50:46'),(84,42,'ms',1,NULL,'SAMC ini telah disahkan melalui Quality Verification. Kredit {credit}, tahap MQF {mqf}, sah hingga {until}.',NULL,'Keluaran awal templat','2025-11-05 04:50:46'),(85,43,'en',1,NULL,'This is an Executive Micro-Credential (MCE). It earns no academic credit, no Academic Credit Record and no deposit to the Academic Bank of Credit.',NULL,'First version','2025-11-05 04:50:46'),(86,43,'ms',1,NULL,'Ini ialah Micro-Credential Eksekutif (MCE). Ia tidak memberi kredit akademik, Academic Credit Record atau deposit ke Academic Bank of Credit.',NULL,'Keluaran awal templat','2025-11-05 04:50:46'),(87,44,'en',1,NULL,'Completing this micro-credential, receiving an Academic Credit Record, depositing credit to the Academic Bank of Credit and transferring credit are separate decisions.',NULL,'First version','2025-11-05 04:50:46'),(88,44,'ms',1,NULL,'Menamatkan micro-credential ini, menerima Academic Credit Record, mendepositkan kredit ke Academic Bank of Credit dan memindahkan kredit adalah keputusan yang berasingan.',NULL,'Keluaran awal templat','2025-11-05 04:50:46'),(89,1,'en',2,'Your MCMS role assignment has been updated','Hello {name}, you now hold the role {role} ({scope}) effective {from}. Governance reason: {reason}.',12,'Clarified governance reason label in role notification.','2026-06-01 10:00:00'),(90,1,'ms',2,'Penetapan peranan MCMS anda telah dikemas kini','Salam {name}, anda kini memegang peranan {role} ({scope}) berkuat kuasa {from}. Sebab tadbir urus: {reason}.',12,'Penambahbaikan istilah tadbir urus.','2026-06-01 10:00:00'),(91,45,'en',1,'Result revised: {title}','Hello {name}, your result for \"{title}\" was revised. What was done: {reason}. Open \"My results\" to see your updated results.',NULL,'First version','2026-11-22 12:27:24'),(92,45,'ms',1,'Keputusan dipinda: {title}','Salam {name}, keputusan anda bagi \"{title}\" telah dipinda. Apa yang dilakukan: {reason}. Buka \"Keputusan saya\" untuk melihat keputusan terkini anda.',NULL,'First version','2026-11-22 12:27:24'),(95,11,'en',2,'Endorsed: {title}','Hello {name}, \"{title}\" has been endorsed by the Deputy Dean and forwarded to CODL for verification and Senate approval.',NULL,'D-66 role governance alignment','2026-11-23 05:50:55'),(96,11,'ms',2,'Disokong: {title}','Salam {name}, \"{title}\" telah disokong oleh Timbalan Dekan dan dimajukan kepada CODL untuk semakan serta kelulusan Senat.',NULL,'D-66 role governance alignment','2026-11-23 05:50:55');
/*!40000 ALTER TABLE `template_versions` ENABLE KEYS */;
